import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_07_01_cheatsheet.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_07_02_best_practices.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_07_03_troubleshooting.png",h="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_07_04_glossary_layers.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_07_05_reference_hierarchy.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_07_06_practice_loop.png",f=JSON.parse('{"title":"Codex 用久了才懂：速查、排障与最佳实践的系统方法","description":"Codex 用得越久，越容易发现真正拖慢工作的不是命令记不住，而是问题分层错误、资料优先级混乱、验证证据不足。速查表只能帮助找到入口，排障方法负责缩小原因空间，最佳实践则把一次成功变成可重复的工作方式。","frontmatter":{"title":"Codex 用久了才懂：速查、排障与最佳实践的系统方法","description":"Codex 用得越久，越容易发现真正拖慢工作的不是命令记不住，而是问题分层错误、资料优先级混乱、验证证据不足。速查表只能帮助找到入口，排障方法负责缩小原因空间，最佳实践则把一次成功变成可重复的工作方式。","date":"2026-08-10","topic":"AI 底层学习","section":"Codex · 官方文档十讲","readingTime":8,"source":"2026-08-10/ai_codex_07_practice_governance.md","status":"published","cover":"/article-assets/2026-08-10/ai_codex_07_01_cheatsheet.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-07-practice-governance"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Codex 用久了才懂：速查、排障与最佳实践的系统方法"}],["meta",{"property":"og:description","content":"Codex 用得越久，越容易发现真正拖慢工作的不是命令记不住，而是问题分层错误、资料优先级混乱、验证证据不足。速查表只能帮助找到入口，排障方法负责缩小原因空间，最佳实践则把一次成功变成可重复的工作方式。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-07-practice-governance"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_07_01_cheatsheet.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"Codex 用久了才懂：速查、排障与最佳实践的系统方法"}],["meta",{"name":"twitter:description","content":"Codex 用得越久，越容易发现真正拖慢工作的不是命令记不住，而是问题分层错误、资料优先级混乱、验证证据不足。速查表只能帮助找到入口，排障方法负责缩小原因空间，最佳实践则把一次成功变成可重复的工作方式。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_07_01_cheatsheet.png"}]],"prev":{"text":"模型不背锅：Codex 选型、提速与迁移的系统方法","link":"/ai/ai-codex-06-model-speed-delivery"},"next":{"text":"敢让 AI 真动手，先把边界画清：Codex 权限、沙箱、审批与安全闭环","link":"/ai/ai-codex-08-security-permissions"}},"headers":[],"relativePath":"ai/ai-codex-07-practice-governance.md","filePath":"ai/ai-codex-07-practice-governance.md","lastUpdated":null}'),s={name:"ai/ai-codex-07-practice-governance.md"};function p(_,a,m,x,u,b){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="codex-用久了才懂-速查、排障与最佳实践的系统方法" tabindex="-1">Codex 用久了才懂：速查、排障与最佳实践的系统方法 <a class="header-anchor" href="#codex-用久了才懂-速查、排障与最佳实践的系统方法" aria-label="Permalink to &quot;Codex 用久了才懂：速查、排障与最佳实践的系统方法&quot;">​</a></h1><p>Codex 用得越久，越容易发现真正拖慢工作的不是命令记不住，而是问题分层错误、资料优先级混乱、验证证据不足。速查表只能帮助找到入口，排障方法负责缩小原因空间，最佳实践则把一次成功变成可重复的工作方式。</p><p>本文以教程第 35～38 篇为线索，对照 OpenAI Docs 的 Best practices、Resources、Troubleshooting 与配置参考，整理稳定的查阅和排障体系。企业治理独立放在本系列第十篇；本篇只解决一个问题：面对不断更新的 Codex，怎样持续找到当前答案并验证它。</p><h2 id="一、速查表应该帮助决策而不是替代理解" tabindex="-1">一、速查表应该帮助决策而不是替代理解 <a class="header-anchor" href="#一、速查表应该帮助决策而不是替代理解" aria-label="Permalink to &quot;一、速查表应该帮助决策而不是替代理解&quot;">​</a></h2><h3 id="_1-1-按任务阶段组织信息" tabindex="-1">1.1 按任务阶段组织信息 <a class="header-anchor" href="#_1-1-按任务阶段组织信息" aria-label="Permalink to &quot;1.1 按任务阶段组织信息&quot;">​</a></h3><p>有用的速查表不应只是命令大全，而应围绕开始、调查、实施、验证和交付组织。开始阶段检查目录、规则和 Git 状态；调查阶段聚焦搜索、日志和调用链；实施阶段关注范围与 diff；验证阶段运行测试；交付阶段记录结果和风险。</p><h3 id="_1-2-只保留稳定入口" tabindex="-1">1.2 只保留稳定入口 <a class="header-anchor" href="#_1-2-只保留稳定入口" aria-label="Permalink to &quot;1.2 只保留稳定入口&quot;">​</a></h3><p>产品界面、模型名称和具体参数可能变化。速查表应优先记录稳定概念和查询方法，例如从当前帮助发现命令，从官方文档核对能力，而不是把一时版本的所有选项刻成永久规则。</p><h3 id="_1-3-把危险动作放在显眼位置" tabindex="-1">1.3 把危险动作放在显眼位置 <a class="header-anchor" href="#_1-3-把危险动作放在显眼位置" aria-label="Permalink to &quot;1.3 把危险动作放在显眼位置&quot;">​</a></h3><p>删除、覆盖工作区、改 Git 历史、处理秘密、推送、部署和发布，应在速查表中单独标记人工确认条件。高风险提醒不能埋在长文末尾。</p><p><img src="'+i+'" alt="图 1：按任务阶段组织的 Codex 速查地图"></p><h2 id="二、最佳实践可以归纳为六个工程习惯" tabindex="-1">二、最佳实践可以归纳为六个工程习惯 <a class="header-anchor" href="#二、最佳实践可以归纳为六个工程习惯" aria-label="Permalink to &quot;二、最佳实践可以归纳为六个工程习惯&quot;">​</a></h2><h3 id="_2-1-给出可验证目标" tabindex="-1">2.1 给出可验证目标 <a class="header-anchor" href="#_2-1-给出可验证目标" aria-label="Permalink to &quot;2.1 给出可验证目标&quot;">​</a></h3><p>把“帮我优化”改为具体行为、允许范围和验收条件。代理越能判断完成状态，越少依赖主观总结。</p><h3 id="_2-2-先调查再实施" tabindex="-1">2.2 先调查再实施 <a class="header-anchor" href="#_2-2-先调查再实施" aria-label="Permalink to &quot;2.2 先调查再实施&quot;">​</a></h3><p>要求代理引用文件、日志、参数和调用关系，区分事实、推断与待确认项。没有证据的原因判断不应直接进入修改。</p><h3 id="_2-3-保持小步差异" tabindex="-1">2.3 保持小步差异 <a class="header-anchor" href="#_2-3-保持小步差异" aria-label="Permalink to &quot;2.3 保持小步差异&quot;">​</a></h3><p>每轮只处理一个清晰目标，避免顺手重构、格式化和添加未要求功能。小 diff 更容易审查，也更容易在失败时定位。</p><h3 id="_2-4-让验证靠近修改" tabindex="-1">2.4 让验证靠近修改 <a class="header-anchor" href="#_2-4-让验证靠近修改" aria-label="Permalink to &quot;2.4 让验证靠近修改&quot;">​</a></h3><p>局部测试应快速运行，完整测试在阶段结束执行。代理每次修改后都获得真实反馈，错误不会积累到最后。</p><h3 id="_2-5-用文档固化稳定规则" tabindex="-1">2.5 用文档固化稳定规则 <a class="header-anchor" href="#_2-5-用文档固化稳定规则" aria-label="Permalink to &quot;2.5 用文档固化稳定规则&quot;">​</a></h3><p>项目目录、构建方式、代码风格和风险边界写进版本化文档，不让每个成员重复解释。会变化的进度与稳定规范分开维护。</p><h3 id="_2-6-保留人工责任点" tabindex="-1">2.6 保留人工责任点 <a class="header-anchor" href="#_2-6-保留人工责任点" aria-label="Permalink to &quot;2.6 保留人工责任点&quot;">​</a></h3><p>架构权衡、安全例外、数据迁移、外部沟通与公开发布需要明确负责人。代理可以准备证据和方案，但不能模糊最终责任。</p><p><img src="'+n+'" alt="图 2：AI 编程的六个稳定工程习惯"></p><h2 id="三、排障先定位失败发生在哪一层" tabindex="-1">三、排障先定位失败发生在哪一层 <a class="header-anchor" href="#三、排障先定位失败发生在哪一层" aria-label="Permalink to &quot;三、排障先定位失败发生在哪一层&quot;">​</a></h2><h3 id="_3-1-理解层失败" tabindex="-1">3.1 理解层失败 <a class="header-anchor" href="#_3-1-理解层失败" aria-label="Permalink to &quot;3.1 理解层失败&quot;">​</a></h3><p>表现为读错目录、忽略项目规则、误解目标或遗漏关键上下文。应重新确认工作目录、适用规则、相关文件和任务合同，而不是立刻更换模型。</p><h3 id="_3-2-权限层失败" tabindex="-1">3.2 权限层失败 <a class="header-anchor" href="#_3-2-权限层失败" aria-label="Permalink to &quot;3.2 权限层失败&quot;">​</a></h3><p>表现为无法写入、不能联网、命令需要批准或凭据缺失。应检查沙箱和授权边界，给出最小例外，不要用更危险的绕过命令。</p><h3 id="_3-3-环境层失败" tabindex="-1">3.3 环境层失败 <a class="header-anchor" href="#_3-3-环境层失败" aria-label="Permalink to &quot;3.3 环境层失败&quot;">​</a></h3><p>表现为依赖缺失、版本不一致、构建缓存污染或平台差异。先用项目声明的方式重建环境，并记录可复现命令。</p><h3 id="_3-4-实现层失败" tabindex="-1">3.4 实现层失败 <a class="header-anchor" href="#_3-4-实现层失败" aria-label="Permalink to &quot;3.4 实现层失败&quot;">​</a></h3><p>表现为测试失败、类型错误、行为回归或性能下降。应从最小复现和失败断言回到因果链，避免连续猜测式补丁。</p><h3 id="_3-5-集成层失败" tabindex="-1">3.5 集成层失败 <a class="header-anchor" href="#_3-5-集成层失败" aria-label="Permalink to &quot;3.5 集成层失败&quot;">​</a></h3><p>表现为 Git 冲突、CI 权限、连接器失效或外部 API 不兼容。应核对当前官方协议、逐字段比较请求和响应，并区分本地成功与远端状态。</p><p><img src="'+c+'" alt="图 3：理解、权限、环境、实现与集成五层排障"></p><h2 id="四、常见问题背后是几组核心边界" tabindex="-1">四、常见问题背后是几组核心边界 <a class="header-anchor" href="#四、常见问题背后是几组核心边界" aria-label="Permalink to &quot;四、常见问题背后是几组核心边界&quot;">​</a></h2><h3 id="_4-1-代理和聊天模型有什么不同" tabindex="-1">4.1 代理和聊天模型有什么不同 <a class="header-anchor" href="#_4-1-代理和聊天模型有什么不同" aria-label="Permalink to &quot;4.1 代理和聊天模型有什么不同&quot;">​</a></h3><p>聊天模型主要生成回答，编码代理还会读取文件、运行命令、修改状态和验证结果。正因为能够行动，它才需要沙箱、批准和审计。</p><h3 id="_4-2-agents-md-和-prompt-谁优先" tabindex="-1">4.2 AGENTS.md 和 Prompt 谁优先 <a class="header-anchor" href="#_4-2-agents-md-和-prompt-谁优先" aria-label="Permalink to &quot;4.2 AGENTS.md 和 Prompt 谁优先&quot;">​</a></h3><p>Prompt 描述本次任务，<code>AGENTS.md</code> 提供所在目录长期适用的项目规则。二者应互补；若出现冲突，需要遵循系统和项目定义的优先级，并向用户指出差异。</p><h3 id="_4-3-mcp、skill-和插件有什么区别" tabindex="-1">4.3 MCP、Skill 和插件有什么区别 <a class="header-anchor" href="#_4-3-mcp、skill-和插件有什么区别" aria-label="Permalink to &quot;4.3 MCP、Skill 和插件有什么区别&quot;">​</a></h3><p>MCP 连接外部工具与数据，Skill 封装可复用工作流，插件把多种能力打包分发。一个插件可以包含 Skill 和 MCP，但三者解决的问题不同。</p><h3 id="_4-4-什么时候使用子代理" tabindex="-1">4.4 什么时候使用子代理 <a class="header-anchor" href="#_4-4-什么时候使用子代理" aria-label="Permalink to &quot;4.4 什么时候使用子代理&quot;">​</a></h3><p>当子任务独立、边界清楚、能够并行并有明确返回产物时使用。频繁共享状态或修改同一文件的工作，更适合由一个代理顺序推进。</p><h3 id="_4-5-为什么自动化后仍要人工审查" tabindex="-1">4.5 为什么自动化后仍要人工审查 <a class="header-anchor" href="#_4-5-为什么自动化后仍要人工审查" aria-label="Permalink to &quot;4.5 为什么自动化后仍要人工审查&quot;">​</a></h3><p>测试只能覆盖被表达出来的要求，代理也可能误解业务意图。人工审查负责判断未编码的约束、风险和组织责任。</p><h2 id="五、统一术语才能统一协作" tabindex="-1">五、统一术语才能统一协作 <a class="header-anchor" href="#五、统一术语才能统一协作" aria-label="Permalink to &quot;五、统一术语才能统一协作&quot;">​</a></h2><h3 id="_5-1-agent-是能执行工具闭环的系统" tabindex="-1">5.1 Agent 是能执行工具闭环的系统 <a class="header-anchor" href="#_5-1-agent-是能执行工具闭环的系统" aria-label="Permalink to &quot;5.1 Agent 是能执行工具闭环的系统&quot;">​</a></h3><p>它不只是底层模型，还包括上下文、工具、规则、权限和运行时。讨论“代理行为”时，需要明确问题发生在哪一层。</p><h3 id="_5-2-sandbox-与-approval-是两道不同边界" tabindex="-1">5.2 Sandbox 与 Approval 是两道不同边界 <a class="header-anchor" href="#_5-2-sandbox-与-approval-是两道不同边界" aria-label="Permalink to &quot;5.2 Sandbox 与 Approval 是两道不同边界&quot;">​</a></h3><p>Sandbox 定义默认技术能力，Approval 决定特定例外是否由人放行。一个是环境约束，一个是决策流程。</p><h3 id="_5-3-context、memory-与-instruction-不应混用" tabindex="-1">5.3 Context、Memory 与 Instruction 不应混用 <a class="header-anchor" href="#_5-3-context、memory-与-instruction-不应混用" aria-label="Permalink to &quot;5.3 Context、Memory 与 Instruction 不应混用&quot;">​</a></h3><p>Context 是当前任务可见材料，Memory 是跨任务保存的经验，Instruction 是需要遵守的指令。材料被看到不代表它拥有最高指令权，历史被记住也不代表它仍然正确。</p><h3 id="_5-4-worktree、thread-与-branch-不是同一概念" tabindex="-1">5.4 Worktree、Thread 与 Branch 不是同一概念 <a class="header-anchor" href="#_5-4-worktree、thread-与-branch-不是同一概念" aria-label="Permalink to &quot;5.4 Worktree、Thread 与 Branch 不是同一概念&quot;">​</a></h3><p>Thread 是会话边界，Worktree 是文件系统中的独立检出，Branch 是 Git 提交线。三者可以组合，但不能互相替代。</p><p><img src="'+h+'" alt="图 4：Codex 核心术语及其所在系统层"></p><h2 id="六、建立不会过时的资料优先级" tabindex="-1">六、建立不会过时的资料优先级 <a class="header-anchor" href="#六、建立不会过时的资料优先级" aria-label="Permalink to &quot;六、建立不会过时的资料优先级&quot;">​</a></h2><h3 id="_6-1-当前帮助负责回答-我这台机器能做什么" tabindex="-1">6.1 当前帮助负责回答“我这台机器能做什么” <a class="header-anchor" href="#_6-1-当前帮助负责回答-我这台机器能做什么" aria-label="Permalink to &quot;6.1 当前帮助负责回答“我这台机器能做什么”&quot;">​</a></h3><p>CLI 的 <code>--help</code>、会话状态和本地配置最接近实际运行版本。遇到命令、参数或配置键问题，先查看当前帮助，再对照官方文档；教程和博客适合解释思路，不应覆盖本机证据。</p><h3 id="_6-2-官方文档负责回答-当前机制如何定义" tabindex="-1">6.2 官方文档负责回答“当前机制如何定义” <a class="header-anchor" href="#_6-2-官方文档负责回答-当前机制如何定义" aria-label="Permalink to &quot;6.2 官方文档负责回答“当前机制如何定义”&quot;">​</a></h3><p>OpenAI Docs 是产品能力、权限、配置和企业边界的优先来源。教程中的模型名、价格、入口名称和实验状态可能随时间变化，应回到官方页面实时核对。</p><h3 id="_6-3-项目规则与运行证据负责回答-这个仓库实际怎样工作" tabindex="-1">6.3 项目规则与运行证据负责回答“这个仓库实际怎样工作” <a class="header-anchor" href="#_6-3-项目规则与运行证据负责回答-这个仓库实际怎样工作" aria-label="Permalink to &quot;6.3 项目规则与运行证据负责回答“这个仓库实际怎样工作”&quot;">​</a></h3><p>官方文档不会知道你的构建命令、目录边界和发布红线。<code>AGENTS.md</code>、<code>ROADMAP.md</code>、仓库源码、当前参数、测试和日志共同构成项目事实。发生冲突时，先分清冲突属于产品版本还是项目现实。</p><p><img src="'+l+'" alt="图 5：当前帮助、官方文档、项目规则与运行证据的优先级"></p><h2 id="七、把一次排障沉淀成下一次的起点" tabindex="-1">七、把一次排障沉淀成下一次的起点 <a class="header-anchor" href="#七、把一次排障沉淀成下一次的起点" aria-label="Permalink to &quot;七、把一次排障沉淀成下一次的起点&quot;">​</a></h2><p>排障完成后，只保留稳定且可验证的结论：问题属于哪一层，最小复现是什么，根因证据在哪里，修改触碰了哪些文件，哪些验证通过，哪些信息仍待确认。重复出现的项目规则写进 <code>AGENTS.md</code>，进度写进 <code>ROADMAP.md</code>，可复用流程再封装成 Skill。</p><p>不要把偶然命令输出、临时路径和未经验证的猜测写成长期知识。经验沉淀的价值不在于记录得多，而在于下次能够快速定位、重新核验并安全更新。</p><p><img src="'+d+'" alt="图 6：问题分层、最小复现、局部修复与经验沉淀闭环"></p><h2 id="八、结语" tabindex="-1">八、结语 <a class="header-anchor" href="#八、结语" aria-label="Permalink to &quot;八、结语&quot;">​</a></h2><p>成熟的 Codex 使用方法不是背完所有功能，而是能稳定回答三个问题：当前事实从哪里查，失败属于哪一层，完成由什么证据证明。只要资料优先级、问题分层和验证闭环清楚，即使产品界面与模型持续更新，团队仍能保持一致的工程判断。</p><h2 id="九、参考资料" tabindex="-1">九、参考资料 <a class="header-anchor" href="#九、参考资料" aria-label="Permalink to &quot;九、参考资料&quot;">​</a></h2><p><a href="https://coding.stormzhang.ai/codex/35-cheatsheet" target="_blank" rel="noreferrer">Codex 系列第 35 篇：速查表</a></p><p><a href="https://coding.stormzhang.ai/codex/36-best-practices" target="_blank" rel="noreferrer">Codex 系列第 36 篇：最佳实践</a></p><p><a href="https://coding.stormzhang.ai/codex/37-faq" target="_blank" rel="noreferrer">Codex 系列第 37 篇：常见问题</a></p><p><a href="https://coding.stormzhang.ai/codex/38-glossary" target="_blank" rel="noreferrer">Codex 系列第 38 篇：术语表</a></p><p><a href="https://learn.chatgpt.com/guides/best-practices" target="_blank" rel="noreferrer">OpenAI Best practices 官方文档</a></p><p><a href="https://learn.chatgpt.com/docs" target="_blank" rel="noreferrer">OpenAI Codex 文档目录</a></p>',79)])])}const g=e(s,[["render",p]]);export{f as __pageData,g as default};
